    (v_route, 'Čachtický hrad', 'Zřícenina hradu na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.72472, 17.76083, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cachtice%2C%20hrad%2C%20Slovensko.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cachtice%2C%20hrad%2C%20Slovensko.jpg"}'::text[], 0, '{"en": {"name": "Čachtice Castle", "description": "Castle. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Čachtice", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Čachticach", "description": "Zamek na Słowacji. Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Čachtice Castle", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Čachtice", "description": "Castillo. Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Čachtice", "description": "Château en ruines en Slovaquie. Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Чахтицький замок", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
