    (v_route, 'Čertova pec', 'Krasová jeskyně ve slovenském pohoří Považský Inovec. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.56028, 17.91528, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Certova%20pec%20%282004%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Certova%20pec%20%282004%29.jpg"}'::text[], 4, '{"en": {"name": "Čertova pec", "description": "Cave and archaeological site in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Čertova pec", "description": "Höhle in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Čertova pec", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Čertova pec", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Čertova pec", "description": "Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Čertova pec", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Čertova pec", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Sĺňava', 'Vodní nádrž a chráněný areál na Slovensku. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.55639, 17.82583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slnava-plachetnica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slnava-plachetnica.jpg"}'::text[], 5, '{"en": {"name": "Sĺňava Reservoir", "description": "A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Sĺňava", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Sĺňava", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Sĺňava", "description": "Stuwmeer in Okres Piešťany, Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Sĺňava", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Sĺňava", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Слнява (водосховище)", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
