    (v_route, 'West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)', 'Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 51.56, 23.54, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bug%20Muhavets.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bug%20Muhavets.jpg"}'::text[], 7, '{"en": {"name": "West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)", "description": "Transboundary Biosphere reserve in Belarus, Poland and Ukraine. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)", "description": "Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)", "description": "Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "West Polesie Transboundary Biosphere Reserve (Belarus/Poland/Ukraine)", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "réserve de biosphère transfrontière de Polésie occidentale", "description": "Réserve de biosphère de l''Unesco située en Pologne, Ukraine et Biélorussie. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Західне Полісся (біосферний заповідник)", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb);
