    (v_route, 'Bazilika svatého Prokopa', 'Kostel v Třebíči. Památka v Česku — kus historie přímo u trasy.', 49.21695, 15.87364, 'http://commons.wikimedia.org/wiki/Special:FilePath/Overview%20of%20Basilica%20of%20Saint%20Procopius%20in%20T%C5%99eb%C3%AD%C4%8D%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Overview%20of%20Basilica%20of%20Saint%20Procopius%20in%20T%C5%99eb%C3%AD%C4%8D%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg"}'::text[], 0, '{"en": {"name": "St. Procopius Basilica in Třebíč", "description": "Church in Třebíč District of Vysočina region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "St. Prokop Basilika", "description": "Kirchengebäude in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Prokopa w Třebíču", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Procopiusbasiliek", "description": "Basiliek in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Procopio", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Procope de Třebíč", "description": "Église de Třebíč, République tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Прокопа", "description": "Церква в Чехії. Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Přední synagoga', 'Synagoga v Třebíči. Památka v Česku — kus historie přímo u trasy.', 49.2172, 15.8769, 'http://commons.wikimedia.org/wiki/Special:FilePath/Exterior%20of%20Old%20synagogue%20in%20Z%C3%A1most%C3%AD%2C%20T%C5%99eb%C3%AD%C4%8D%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Exterior%20of%20Old%20synagogue%20in%20Z%C3%A1most%C3%AD%2C%20T%C5%99eb%C3%AD%C4%8D%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg"}'::text[], 1, '{"en": {"name": "Old synagogue", "description": "Synagogue in Třebíč. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Altschul", "description": "Synagoge in Trebitsch. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Przednia Synagoga w Třebíču", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Přední synagoga", "description": "Synagoge in Třebíč, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Přední synagoga", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Přední synagoga", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Přední synagoga", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
