    (v_route, 'Hošťanka', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.1655, 15.8718, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trebic%20slavice%20hostanka%20stromy.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trebic%20slavice%20hostanka%20stromy.jpg"}'::text[], 3, '{"en": {"name": "Hošťanka", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Hošťanka", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Hošťanka", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Hošťanka", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Hošťanka", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Hošťanka", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Hošťanka", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'vodní nádrž Dalešice', 'Vodní nádrž na Jihlavě v okrese Třebíč. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.1388, 16.10464, 'http://commons.wikimedia.org/wiki/Special:FilePath/Beach%20at%20camp%20Hartv%C3%ADkovice%20beach%20at%20Dale%C5%A1ice%20Reservoir%20near%20Hartv%C3%ADkovice%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Beach%20at%20camp%20Hartv%C3%ADkovice%20beach%20at%20Dale%C5%A1ice%20Reservoir%20near%20Hartv%C3%ADkovice%2C%20T%C5%99eb%C3%AD%C4%8D%20District.jpg"}'::text[], 4, '{"en": {"name": "Dalešice Reservoir", "description": "Reservoir in Dalešice, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Wasserkraftwerk Dalešice", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Dalešice", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Dalešice", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Dalešice", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Dalešice", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Dalešice", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
