    (v_route, 'Levnov', 'Zřícenina hradu palácové existujícího patrně od konce 13. st. do r. 1440, kdy byl dobyt a rozbořen vojskem královských měst. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.13917, 16.23972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Levnov.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Levnov.jpg"}'::text[], 6, '{"en": {"name": "Levnov", "description": "Castle. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Levnov", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Levnov", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Levnov", "description": "Kasteel in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Levnov", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Levnov", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Levnov", "description": "Замок (споруда). Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
