    (v_route, 'Bazilika svatých Petra a Pavla v Poznani', 'Katedrála v Poznani. Památka v Polsku — kus historie přímo u trasy.', 52.41139, 16.94778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Poznan%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Poznan%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2010.jpg"}'::text[], 0, '{"en": {"name": "Archcathedral Basilica of St. Peter and St. Paul", "description": "Polish cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Posener Dom", "description": "Kirchengebäude in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna Świętych Apostołów Piotra i Pawła w Poznaniu", "description": "Świątynia katolicka, katedra. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Petrus-en-Paulusbasiliek", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Poznań", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saints-Pierre-et-Saint-Paul de Poznan", "description": "Église à Poznań en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святих Петра і Павла", "description": "Катедральний собор в Познані, Польща. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Royal Castle, Poznań', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.40913, 16.93098, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20Real%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2042.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20Real%2C%20Poznan%2C%20Polonia%2C%202014-09-18%2C%20DD%2042.jpg"}'::text[], 1, '{"en": {"name": "Royal Castle, Poznań", "description": "Castle. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Posener Königsschloss", "description": "Schloss in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Królewski w Poznaniu", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Royal Castle, Poznań", "description": "Kasteel in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Real", "description": "Monumento de Poznań. Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château royal de Poznań", "description": "Château en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Познанський королівський замок", "description": "Замок (споруда). Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Poznaň', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.4219, 16.9352, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brama%20Berli%C5%84ska%20Pozna%C5%84.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brama%20Berli%C5%84ska%20Pozna%C5%84.jpg"}'::text[], 2, '{"en": {"name": "Poznań Fortress", "description": "Set of fortifications in the city of Poznań in western Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Festung Posen", "description": "Reihe von Befestigungsanlagen in der Stadt Posen in Westpolen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Poznań", "description": "Zespół fortyfikacji w Poznaniu. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Vesting Poznań", "description": "Vesting in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza de Poznań", "description": "Conjunto de fortificaciones construidas en la ciudad de Poznań, Polonia. Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Poznań", "description": "Fortifications à Poznań, Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Познанська фортеця", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Malta', 'Umělá vodní nádrž v Polsku ve městě Poznaň s veslařskou dráhou. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 52.4025, 16.97083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Malta%20Trybuny%20Pozna%C5%84%20RB1.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Malta%20Trybuny%20Pozna%C5%84%20RB1.JPG"}'::text[], 3, '{"en": {"name": "Lake Malta", "description": "Artificial lake in Poznan, Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Maltasee", "description": "Künstlicher See in der Stadt Posen, Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Maltańskie", "description": "Sztuczny zbiornik wodny w Poznaniu. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lake Malta", "description": "Stuwmeer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Malta", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Malta", "description": "Lac artificiel. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Malta", "description": "Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
