    (v_route, 'Morasko Meteorite Nature Reserve', 'Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.49, 16.89639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Morasko%20krater%20zima.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Morasko%20krater%20zima.jpg"}'::text[], 5, '{"en": {"name": "Morasko Meteorite Nature Reserve", "description": "Impact crater reserve in Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Morasko", "description": "Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Morasko", "description": "Rezerwat przyrody. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Morasko Meteorite Nature Reserve", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Morasko Meteorite Nature Reserve", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Réserve naturelle de la météorite de Morasko", "description": "Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Morasko", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Velkopolský národní park', 'Chráněné území v Polsku. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.27556, 16.81583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wielkopolski%20National%20Park%20okolica%20Trzecielinskiego%20Bagna%29%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wielkopolski%20National%20Park%20okolica%20Trzecielinskiego%20Bagna%29%20%281%29.jpg"}'::text[], 6, '{"en": {"name": "Wielkopolska National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Wielkopolski-Nationalpark", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Wielkopolski Park Narodowy", "description": "Park narodowy w Polsce. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Wielkopolska", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Wielkopolska", "description": "Parque nacional dentro de Gran Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Wielkopolska", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Великопольський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Kórnik', 'Zámek v Kórniku. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.24392, 17.09084, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20K%C3%B3rnik%2C%20K%C3%B3rnik%2C%20Polonia%2C%202016-12-21%2C%20DD%2004.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20K%C3%B3rnik%2C%20K%C3%B3rnik%2C%20Polonia%2C%202016-12-21%2C%20DD%2004.jpg"}'::text[], 7, '{"en": {"name": "Kórnik Castle", "description": "Castle. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Schloss Kórnik", "description": "Schloss in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Kórniku", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kórnik", "description": "Kasteel in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Kórnik", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Kórnik", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Курницький замок", "description": "Замок (споруда). Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb);
