    (v_route, 'Stachelberg', 'Rozestavěná dělostřelecká tvrz u Trutnova. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 50.62783, 15.91157, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trutnov%2C%20Bab%C3%AD%2C%20T-S%2073%20%28rok%202012%3B%2001%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trutnov%2C%20Bab%C3%AD%2C%20T-S%2073%20%28rok%202012%3B%2001%29.jpg"}'::text[], 5, '{"en": {"name": "Stachelberg", "description": "Fortress in the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Festung Stachelberg", "description": "Museum in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Grupa Warowna Stachelberg", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Stachelberg", "description": "Fortificatie in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Stachelberg", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Stachelberg", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Stachelberg", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
