    (v_route, 'Národní park Slovenský kras', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.579, 20.544, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zadielska%20tiesnava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zadielska%20tiesnava.jpg"}'::text[], 5, '{"en": {"name": "Slovak Karst National Park", "description": "National park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Slowakischer Karst", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Kras Słowacki", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Slowaakse Karst", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Slovenský Kras", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national du karst de Slovaquie", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк «Словацький карст»", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Strážní věž', 'Strážní věž v Rožňavě. Rozhledna v Slovensku — výhled do kraje jako odměna za zastávku.', 48.66217, 20.53299, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava%20-%20Str%C3%A1%C5%BEna%20ve%C5%BEa%20-1a.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ro%C5%BE%C5%88ava%20-%20Str%C3%A1%C5%BEna%20ve%C5%BEa%20-1a.jpg"}'::text[], 6, '{"en": {"name": "Tower in Rožňava", "description": "Observation tower in Rožňava, Slovakia. A lookout tower in Slovakia — sweeping views as a reward for stopping."}, "de": {"name": "Strážní věž", "description": "Ein Aussichtsturm in der Slowakei — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża strażnicza w Rożniawie", "description": "Wieża widokowa w Słowacji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Wachttoren", "description": "Uitkijktoren in Rožňava, Slowakije. Een uitkijktoren in Slowakije — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Strážní věž", "description": "Un mirador en Eslovaquia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Strážní věž", "description": "Une tour panoramique en Slovaquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Strážní věž", "description": "Оглядова вежа в Словаччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Krásna Hôrka', 'Hrad. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.65824, 20.60033, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG"}'::text[], 7, '{"en": {"name": "Krásna Hôrka Castle", "description": "Castle. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Krásna Hôrka", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Krásna Hôrka", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Krásna Hôrka", "description": "Kasteel in Krásnohorské Podhradie, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Krásna Hôrka", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Krásna Hôrka", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Красна Гурка", "description": "Замок (споруда). Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb);
