    (v_route, 'Katedrála svaté Alžběty v Košicích', 'Katedrála v Košicích. Památka v Slovensku — kus historie přímo u trasy.', 48.72049, 21.25759, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20Elizabeth%20in%20Ko%C5%A1ice.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20of%20St.%20Elizabeth%20in%20Ko%C5%A1ice.jpg"}'::text[], 0, '{"en": {"name": "Cathedral of St. Elizabeth", "description": "Cathedral in Košice, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Elisabethdom", "description": "Kirchengebäude in Košice, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Elżbiety w Koszycach", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Košice", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Košice", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Élisabeth de Košice", "description": "Édifice religieux situé en Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святої Єлизавети Угорської", "description": "Собор у Кошиці (Словаччина). Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
