    (v_route, 'Zamek Golesz w Krajowicach', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 49.7779, 21.44129, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Golesz%20w%20Krajowicach.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Golesz%20w%20Krajowicach.jpg"}'::text[], 5, '{"en": {"name": "Zamek Golesz w Krajowicach", "description": "A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Burg Golesz", "description": "Abgegangene Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Golesz w Krajowicach", "description": "Ruiny zamku w Polsce. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zamek Golesz w Krajowicach", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Zamek Golesz w Krajowicach", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Zamek Golesz w Krajowicach", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Zamek Golesz w Krajowicach", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb);
