    (v_route, 'Katedrála Nanebevzetí Panny Marie v Gurku', 'Katedrála v Korutanech v Rakousku. Památka v Rakousku — kus historie přímo u trasy.', 46.875, 14.2936, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gurk%20Cathedral.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gurk%20Cathedral.jpg"}'::text[], 0, '{"en": {"name": "Gurk Cathedral", "description": "Church in Carinthia, Austria. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Dom zu Gurk", "description": "Kirchengebäude in Gurk, Kärnten. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Gurk", "description": "Świątynia katolicka. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Gurk", "description": "Kathedraal in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Gurk", "description": "Basílica de Carintia, Austria. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Assomption-de-Marie de Gurk", "description": "Cocathédrale à Gurk, Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор у Ґурку", "description": "Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
