    (v_route, 'klášter svatého Lamberta', 'Benediktinské opatství v Rakousku. Památka v Rakousku — kus historie přímo u trasy.', 47.0716, 14.3007, 'http://commons.wikimedia.org/wiki/Special:FilePath/St.Lambrecht%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St.Lambrecht%20-%20panoramio.jpg"}'::text[], 3, '{"en": {"name": "St. Lambert''s Abbey", "description": "Benedictine Abbey. A heritage sight in Austria — a piece of history right on your route."}, "de": {"name": "Stift St. Lambrecht", "description": "Benediktinerabtei in Sankt Lambrecht, Steiermark. Ein Denkmal in Österreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Sankt Lambrecht", "description": "Muzeum w Austrii. Zabytek w Austrii — kawałek historii tuż przy trasie."}, "nl": {"name": "Stift Sankt Lambrecht", "description": "Kerkgebouw in Oostenrijk. Een monument in Oostenrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "klášter svatého Lamberta", "description": "Museo en Austria. Un monumento en Austria: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Saint Lambert", "description": "Abbaye en Autriche. Un monument en Autriche — un morceau d''histoire au bord de la route."}, "uk": {"name": "Абатство Святого Ламбрехта", "description": "Бенедиктинський монастир в с. Санкт Ламбрехт, що знаходиться в природному парку Гребенцен в Штирії, Австрія. Пам''ятка в Австрії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Längsee', 'Vodní plocha v Rakousku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.7894, 14.4242, 'http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Georgen%20am%20L%C3%A4ngsee%20-%20L%C3%A4ngsee.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Georgen%20am%20L%C3%A4ngsee%20-%20L%C3%A4ngsee.JPG"}'::text[], 4, '{"en": {"name": "Längsee", "description": "Lake in Carinthia, Austria. A body of water in Austria — a pleasant ride destination with waterside views."}, "de": {"name": "Längsee", "description": "See in Kärnten. Ein Gewässer in Österreich — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Längsee", "description": "Akwen w Austrii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Längsee", "description": "Meer in Oostenrijk. Een waterpartij in Oostenrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Längsee", "description": "Una masa de agua en Austria: un destino agradable con vistas al agua."}, "fr": {"name": "Längsee", "description": "Un plan d''eau en Autriche — une belle destination avec vue sur l''eau."}, "uk": {"name": "Längsee", "description": "Сторінка значень у проєкті Вікімедіа. Водойма в Австрії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Saint George''s Abbey, Längsee', 'Hrad či zámek v Rakousku — historická zastávka, která stojí za odbočku.', 46.7811, 14.4303, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Georgen%20am%20Laengsee%20Schlossallee%206%20Stift%20St%20Georgen%2012092015%207291.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sankt%20Georgen%20am%20Laengsee%20Schlossallee%206%20Stift%20St%20Georgen%2012092015%207291.jpg"}'::text[], 5, '{"en": {"name": "Saint George''s Abbey, Längsee", "description": "Church building in St. Georgen am Längsee, Austria. A castle in Austria — a historic stop worth the detour."}, "de": {"name": "Stift St. Georgen", "description": "Ehemaliges Bendiktinerinnenstift in St. Georgen am Längsee, Kärnten. Eine Burg bzw. ein Schloss in Österreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Saint George''s Abbey, Längsee", "description": "Zamek w Austrii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Stift van Sankt Georgen am Längsee", "description": "Kerkgebouw in Oostenrijk. Een kasteel in Oostenrijk — een historische stop die de omweg waard is."}, "es": {"name": "Saint George''s Abbey, Längsee", "description": "Un castillo en Austria: una parada histórica que merece el desvío."}, "fr": {"name": "Saint George''s Abbey, Längsee", "description": "Église autrichienne. Un château en Autriche — une halte historique qui vaut le détour."}, "uk": {"name": "Saint George''s Abbey, Längsee", "description": "Замок у Австрії — історична зупинка, варта об''їзду."}}'::jsonb),
