    (v_route, 'Národní park Ústí Warty', 'Národní park v Polsku. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.5772, 14.7258, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ujscie%20Warty%20PN%2009-2017%20img04.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ujscie%20Warty%20PN%2009-2017%20img04.jpg"}'::text[], 0, '{"en": {"name": "Ujście Warty National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Warthemündung", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy „Ujście Warty”", "description": "Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Wartamonding", "description": "Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Ujście Warty", "description": "Parque nacional de Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national d''Ujście Warty", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Уйсце Варти", "description": "Національний парк у Польщі. Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Joannites Castle in Słońsk', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.5708, 14.8067, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20S%C5%82o%C5%84sk.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20S%C5%82o%C5%84sk.jpg"}'::text[], 1, '{"en": {"name": "Joannites Castle in Słońsk", "description": "A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Ordensschloss Sonnenburg", "description": "Schlossruine in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek joannitów w Słońsku", "description": "Zabytek nieruchomy w województwie lubuskim. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Joannites Castle in Słońsk", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Joannites Castle in Słońsk", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "Joannites Castle in Słońsk", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Joannites Castle in Słońsk", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Kostrzyn nad Odrą Fortress', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.57907, 14.62898, 'http://commons.wikimedia.org/wiki/Special:FilePath/KostrzynNadOdra%2009-2017%20img4.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/KostrzynNadOdra%2009-2017%20img4.jpg"}'::text[], 2, '{"en": {"name": "Kostrzyn nad Odrą Fortress", "description": "Fortress in Poland and Germany. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Festung Küstrin", "description": "Bauwerk zum Schutz der Residenzstadt Küstrin, in der zweiten Hälfte des 16. Jahrhunderts errichtet. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Kostrzyn", "description": "Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kostrzyn nad Odrą Fortress", "description": "Vesting in Duitsland. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Kostrzyn nad Odrą Fortress", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Custrin", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Kostrzyn nad Odrą Fortress", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Remains Kleist Tower in Słubice', 'Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 52.345, 14.5945, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frankfurt%20a.%20O.%20Kleist-Turm.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frankfurt%20a.%20O.%20Kleist-Turm.jpg"}'::text[], 3, '{"en": {"name": "Remains Kleist Tower in Słubice", "description": "A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Frankfurter Kleistturm", "description": "Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża Kleista we Frankfurcie nad Odrą", "description": "Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Remains Kleist Tower in Słubice", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Remains Kleist Tower in Słubice", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "Remains Kleist Tower in Słubice", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Remains Kleist Tower in Słubice", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Głębiniec', 'Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 52.32219, 14.75651, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20G%C5%82%C4%99biniec%20-%20ziemia%20lubuska%2C%20powiat%20s%C5%82ubicki.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20G%C5%82%C4%99biniec%20-%20ziemia%20lubuska%2C%20powiat%20s%C5%82ubicki.jpg"}'::text[], 4, '{"en": {"name": "Głębiniec", "description": "Lake in Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Głębiniec", "description": "See in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Głębiniec", "description": "Jezioro na Równinie Torzymskiej, położone w województwie lubuskim wśród lasów Puszczy Rzepińskiej. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Głębiniec", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Głębiniec", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Głębiniec", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Głębiniec", "description": "Озеро в Польщі. Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Linie', 'Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 52.31687, 14.78399, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20Linie.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jezioro%20Linie.jpg"}'::text[], 5, '{"en": {"name": "Linie", "description": "Lake in Lubusz Voivodeship, Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Linie", "description": "Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Linie", "description": "Jezioro na Równinie Torzymskiej, w powiecie słubickim, położone jest wśród lasów Puszczy Rzepińskiej. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Linie", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Linie", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Linie", "description": "Lac. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Linie", "description": "Озеро. Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
