    (v_route, 'Národní park Muráňská planina', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.78333, 20.03333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88sk%C3%A1%20planina%20%282%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88sk%C3%A1%20planina%20%282%29.JPG"}'::text[], 0, '{"en": {"name": "Muránska planina National Park", "description": "Slovak national park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Muraner Hochebene", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Płaskowyż Murański", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Muránska Planina", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Muránska Planina", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Muránska planina", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк Муранська полонина", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
