    (v_route, 'Národní park Tucholské bory', 'Národní park v Polsku. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 53.8, 17.56, 'http://commons.wikimedia.org/wiki/Special:FilePath/Witacz%20w%20Parku%20Narodowym%20Bory%20Tucholskie%2003.07.10%20p.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Witacz%20w%20Parku%20Narodowym%20Bory%20Tucholskie%2003.07.10%20p.jpg"}'::text[], 0, '{"en": {"name": "Bory Tucholskie National Park", "description": "Protected area on the Charzykowska Plain in Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Bory Tucholskie", "description": "Nationalpark in der Woiwodschaft Pommern in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy „Bory Tucholskie”", "description": "Obszar objęty ochroną na Równinie Charzykowskiej w Polsce. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Bory Tucholskie", "description": "Natuurgebied in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Bory Tucholskie", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de la forêt de Tuchola", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк „Тухольські Бори“", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
