    (v_route, 'Katedrála svatého Jana Křtitele ve Vratislavi', 'Katedrála v polské Vratislavi. Památka v Polsku — kus historie přímo u trasy.', 51.11417, 17.04658, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wroc%C5%82aw%20-%20Archikatedra%20%C5%9Bw.%20Jana%20Chrzciciela%20%281%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wroc%C5%82aw%20-%20Archikatedra%20%C5%9Bw.%20Jana%20Chrzciciela%20%281%29.jpg"}'::text[], 0, '{"en": {"name": "Wrocław Cathedral", "description": "Historic catholic church in Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Breslauer Dom", "description": "Kirchengebäude in Breslau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "archikatedra św. Jana Chrzciciela we Wrocławiu", "description": "Zabytkowa świątynia rzymskokatolicka w Polsce. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Wrocław Cathedral", "description": "Kathedraal in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Breslavia", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-Baptiste de Wrocław", "description": "Cathédrale polonaise. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Івана Хрестителя (Вроцлав)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'katedrála svatého Vincenta a svatého Jakuba', 'Řeckokatolická katedrála ve Vratislavi. Památka v Polsku — kus historie přímo u trasy.', 51.11278, 17.03806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wroclaw%20kosciol%20swWincentego.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wroclaw%20kosciol%20swWincentego.jpg"}'::text[], 1, '{"en": {"name": "Church of St. Vincent", "description": "Ukrainian Catholic cathedral in Wrocław, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "St. Vinzenz", "description": "Kirchengebäude in Breslau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór św. Wincentego i św. Jakuba we Wrocławiu", "description": "Katedra greckokatolicka we Wrocławiu. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "H.H. Vincentius- en Jacobuskathedraal", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Vicente y Santiago", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Saint-Vincent", "description": "Lieu de culte catholique en Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Вінсента", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
