    (v_route, 'Vodárenská věž', 'Vodárenská věž ve Vratislavi Borek. Rozhledna v Polsku — výhled do kraje jako odměna za zastávku.', 51.08523, 17.01756, 'http://commons.wikimedia.org/wiki/Special:FilePath/Breslau%20Wroclaw%20Wasserturm.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Breslau%20Wroclaw%20Wasserturm.jpg"}'::text[], 4, '{"en": {"name": "Wrocław water tower", "description": "Water tower in Poland. A lookout tower in Poland — sweeping views as a reward for stopping."}, "de": {"name": "Wasserturm Breslau", "description": "Ein Aussichtsturm in Polen — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża ciśnień przy alei Wiśniowej we Wrocławiu", "description": "Zabytek nieruchomy w województwie dolnośląskim. Wieża widokowa w Polsce — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Wrocław water tower", "description": "Een uitkijktoren in Polen — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Vodárenská věž", "description": "Un mirador en Polonia: amplias vistas como recompensa por la parada."}, "fr": {"name": "château d''eau de l''allée Wiśniowa de Wrocław", "description": "Une tour panoramique en Pologne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Вроцлавська водонапірна вежа", "description": "Оглядова вежа в Польщі — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
