    (v_route, 'Sanctuary of St. Jadwiga in Trzebnica', 'Památka v Polsku — kus historie přímo u trasy.', 51.30917, 17.06667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Trzebnica%20-%20sanctuary%20of%20Hedwig.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Trzebnica%20-%20sanctuary%20of%20Hedwig.jpg"}'::text[], 7, '{"en": {"name": "Sanctuary of St. Jadwiga in Trzebnica", "description": "Abbey. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kloster Trebnitz", "description": "Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sanktuarium św. Jadwigi w Trzebnicy", "description": "Zabytek nieruchomy w województwie dolnośląskim. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Sanctuary of St. Jadwiga in Trzebnica", "description": "Abdij in Trzebnica, Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Santuario de Santa Eduviges en Trzebnica", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Sainte-Hedwige", "description": "Ancienne abbaye cistercienne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Sanctuary of St. Jadwiga in Trzebnica", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb);
