    (v_route, 'Roztoczanský národní park', 'Národní park v Polsku. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 50.61667, 22.96667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Koniki%20polskie%20RPN2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Koniki%20polskie%20RPN2.jpg"}'::text[], 0, '{"en": {"name": "Roztocze National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Roztocze", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Roztoczański Park Narodowy", "description": "Park narodowy położony na Roztoczu. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal park Roztocze", "description": "Natuurgebied in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Roztocze", "description": "Parque nacional de Polonia. Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Roztocze", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Розточанський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb),
