    (v_route, 'Nielisz', 'Přehrada na řece Wieprz v Polsku. Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 50.78608, 23.02082, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zalewnielisz%20070.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zalewnielisz%20070.jpg"}'::text[], 2, '{"en": {"name": "Nielisz Lake", "description": "A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Nielisz", "description": "Stausee in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zalew Nielisz", "description": "Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Nielisz", "description": "Stuwmeer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Nielisz", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Nielisz", "description": "Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Nielisz", "description": "Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Katedrála Zmrtvýchvstání a svatého Tomáše v Zámostí', 'Katedrála v Polsku. Památka v Polsku — kus historie přímo u trasy.', 50.7164, 23.2503, 'http://commons.wikimedia.org/wiki/Special:FilePath/Katedra%20Zamosc%202013.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Katedra%20Zamosc%202013.JPG"}'::text[], 3, '{"en": {"name": "Cathedral of the Resurrection and St. Thomas the Apostle, Zamość", "description": "Church building in Zamość, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Kollegiatkirche", "description": "Kirchengebäude in Polen. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Zmartwychwstania Pańskiego i św. Tomasza Apostoła w Zamościu", "description": "Świątynia katolicka, zabytek renesansowy. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van de Verrijzenis van Tomas de Apostel", "description": "Kerkgebouw in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Resurrección y Santo Tomás", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de la Résurrection-et-Saint-Thomas de Zamość", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Латинська катедра (Замостя)", "description": "Церква в Польщі. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Zamość Fortress', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 50.717, 23.2526, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oldlubelskagate.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oldlubelskagate.jpg"}'::text[], 4, '{"en": {"name": "Zamość Fortress", "description": "Deconstructed fortress, museum and heritage site. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Zamość Fortress", "description": "Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Zamość", "description": "Fortyfikacje otaczające Zamość (Polska; budowa: 1579–1618). Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Zamość Fortress", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Zamość Fortress", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Zamość", "description": "Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Замойська фортеця", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Zamość Synagogue', 'Památka v Polsku — kus historie přímo u trasy.', 50.71799, 23.25417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20Zamo%C5%9B%C4%87%20VIII%202010.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20Zamo%C5%9B%C4%87%20VIII%202010.jpg"}'::text[], 5, '{"en": {"name": "Zamość Synagogue", "description": "Former synagogue in Zamość, Poland. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Zamościu", "description": "Synagoga w Polsce. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Zamość Synagogue", "description": "Synagoge in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga Zamość", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Zamość", "description": "Synagogue du sud-est de la Pologne. Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Zamość Synagogue", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
