    (v_route, 'Katedrála svatého Bartoloměje', 'Kostel v Plzni. Památka v Česku — kus historie přímo u trasy.', 49.74757, 13.37761, 'http://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88%20Cathedral%20of%20Saint%20Bartholomew-0146%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Plze%C5%88%20Cathedral%20of%20Saint%20Bartholomew-0146%20crop.jpg"}'::text[], 0, '{"en": {"name": "Cathedral of St. Bartholomew", "description": "Church in Plzeň-město District of Plzeň region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "St.-Bartholomäus-Kathedrale", "description": "Kathedrale in Pilsen, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Bartłomieja w Pilznie", "description": "Świątynia katolicka. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Pilsen", "description": "Bouwwerk in Pilsen (regio). Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "catedral de San Bartolomé", "description": "Edificio religioso en Pilsen, República Checa. Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Barthélemy de Pilsen", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Bartoloměje", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
