    (v_route, 'Červený Kameň', 'Hrad na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.39167, 17.33556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cerveny%20Kamen%20z%20Kukly%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cerveny%20Kamen%20z%20Kukly%2002.jpg"}'::text[], 0, '{"en": {"name": "Červený Kameň Castle", "description": "Castle in Slovakia. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Červený Kameň", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Czerwony Kamień", "description": "Zamek na Słowacji. Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Červený Kameň", "description": "Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Červený Kameň", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Červený Kameň", "description": "Château en Slovaquie. Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Червений камінь", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
