    (v_route, 'Jeskyně Driny', 'Národní přírodní památka na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.50056, 17.40389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Driny%20cave%20interior%2012.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Driny%20cave%20interior%2012.JPG"}'::text[], 2, '{"en": {"name": "Driny", "description": "Cave, national natural monument in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Driny", "description": "Höhle in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Driny", "description": "Jaskinia krasowa na Słowacji. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Driny", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Driny", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Jeskyně Driny", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Jeskyně Driny", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Smolenický zámek', 'Zámek na Slovensku v okrese Trnava. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.51361, 17.43222, 'http://commons.wikimedia.org/wiki/Special:FilePath/Smolenice%20zamok.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Smolenice%20zamok.jpg"}'::text[], 3, '{"en": {"name": "Smolenice Castle", "description": "Castle in Slovakia. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Schloss Smolenice", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac w Smolenicach", "description": "Zamek w słowackiej miejscowości Smolenice. Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Smolenice Castle", "description": "Kasteel in Smolenice, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Smolenice", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Smolenický zámek", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Смоленицький замок", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Jana Křtitele v Trnavě', 'Kostel v Trnavě. Památka v Slovensku — kus historie přímo u trasy.', 48.3804, 17.58809, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20-%20Cathedral%20of%20St.%20John%20the%20Baptist.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20-%20Cathedral%20of%20St.%20John%20the%20Baptist.jpg"}'::text[], 4, '{"en": {"name": "St. John the Baptist Cathedral", "description": "Cathedral in Trnava. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kathedrale des heiligen Johannes des Täufers", "description": "Kathedrale in Trnava. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jana Chrzciciela w Trnawie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Johannes de Doper", "description": "Kathedraal in Trnava. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Bautista", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-Baptiste de Trnava", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Jana Křtitele v Trnavě", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Synagoga status quo ante', 'Synagoga v Trnavě. Památka v Slovensku — kus historie přímo u trasy.', 48.37807, 17.59018, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20synagogue%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20synagogue%2001.jpg"}'::text[], 5, '{"en": {"name": "Synagogue in Trnava", "description": "Former synagogue in Trnava, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Gebäude in Trnava, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Trnawie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagogue in Trnava", "description": "Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Trnava", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Synagoga status quo ante", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga status quo ante", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika sv. Mikuláše v Trnavě', 'Trojlodní gotická basilika se dvěma věžemi v průčelí z let 1380–1421, v letech 1543–1820 uherská a v letech 1918–1977 slovenská katedrála. Památka v Slovensku — kus historie přímo u trasy.', 48.37909, 17.59236, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia-Trnava-Kostol%20svateho%20Mikulasa%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia-Trnava-Kostol%20svateho%20Mikulasa%201.JPG"}'::text[], 6, '{"en": {"name": "Saint Nicolas'' Church, Trnava", "description": "Church. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Nikolaus-Dom", "description": "Dom in der Altstadt von Trnava (Tyrnau) in der Westslowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Mikołaja w Trnawie", "description": "Zabytkowa świątynia rzymskokatolicka w Słowacji. Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Bazilika sv. Mikuláše v Trnavě", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Bazilika sv. Mikuláše v Trnavě", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique saint Nicolas de Trnava", "description": "Église catholique classée (ancienne cathédrale) de Trnava (Slovaquie occidentale). Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bazilika sv. Mikuláše v Trnavě", "description": "Церква. Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Zlaté piesky', 'Jezero v Bratislavě. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.18472, 17.18944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zlatepiesky.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zlatepiesky.jpg"}'::text[], 7, '{"en": {"name": "Zlaté Piesky", "description": "Lake in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Zlaté piesky", "description": "See in Bratislava. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zlaté piesky", "description": "Jezioro w Bratysławie. Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Zlaté piesky", "description": "Meer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Zlatle Piesky", "description": "Lago en Eslovaquia. Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Zlaté piesky", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Zlaté piesky", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
