    (v_route, 'Kráľová', 'Vodní nádrž na řece Váh. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.22639, 17.80722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia-Kralova-Kaskady%203.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia-Kralova-Kaskady%203.JPG"}'::text[], 7, '{"en": {"name": "Kráľová Reservoir", "description": "Reservoir in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Kráľová", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Kráľová", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Kráľová", "description": "Stuwmeer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Kráľová", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Kráľová", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Кральова", "description": "Водосховище на річці Ваг, Словаччина. Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
