    (v_route, 'Oravská přehrada', 'Přehradní nádrž na severu Slovenska. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.4, 19.55, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Orava%203.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Orava%203.jpg"}'::text[], 0, '{"en": {"name": "Orava", "description": "Reservoir in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Orava-Stausee", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Orawskie", "description": "Zbiornik retencyjny (Kraj żyliński, Słowacja). Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Orava", "description": "Stuwmeer in Žilina, Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Oravská přehrada", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Oravská přehrada", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Орава", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Brestovská jeskyně', 'Národní přírodní památka. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.25817, 19.66098, 'http://commons.wikimedia.org/wiki/Special:FilePath/National%20natural%20monument%20Brestovska%20jaskyna%20%2815%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/National%20natural%20monument%20Brestovska%20jaskyna%20%2815%29.jpg"}'::text[], 1, '{"en": {"name": "Brestovská jaskyňa (national natural monument)", "description": "Cave in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Brestovská jaskyňa", "description": "Höhle in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Jaskinia Brestowska", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Brestovská jeskyně", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Brestovska jaskyna", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Brestovská jeskyně", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Brestovská jeskyně", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
