:text[], false, 5448, 'approved', '{"en": {"name": "Highlights around Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "A points-of-interest ride in Poland: Oliwa Cathedral, Abbot''s Palace (Oliwa), Lighthouse in Sopot, Wisłoujście Fortress…. 8 stops over roughly 25 km — reorder them in the app and navigate right away."}, "de": {"name": "Highlights rund um Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Eine Tour zu Sehenswürdigkeiten in Polen: Dom zu Oliva, Äbtepalast zu Oliva, Maják v Sopotech, Festung Weichselmünde…. 8 Stopps auf rund 25 km — Reihenfolge in der App anpassbar, Navigation direkt aus der App."}, "pl": {"name": "Najlepsze w okolicy: Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Wycieczka po ciekawych miejscach w Polsce: Bazylika Archikatedralna Trójcy Świętej w Gdańsku-Oliwie, Pałac Opatów w Oliwie, Latarnia Morska Sopot, Twierdza Wisłoujście…. Łącznie 8 przystanków na około 25 km — kolejność zmienisz w aplikacji i od razu nawigujesz."}, "nl": {"name": "Hoogtepunten rond Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Een rit langs bezienswaardigheden in Polen: Kathedraal van Oliwa, Abtpaleis Oliwa, Maják v Sopotech, Wisłoujście Fortress…. 8 stops over zo''n 25 km — pas de volgorde aan in de app en navigeer direct."}, "es": {"name": "Lo mejor cerca de Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Una ruta por puntos de interés en Polonia: Catedral de Oliwa, Abbot''s Palace (Oliwa), Maják v Sopotech, Wisłoujście Fortress…. 8 paradas en unos 25 km; reordénalas en la app y navega al instante."}, "fr": {"name": "Les incontournables autour de Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Une virée entre points d''intérêt en Pologne : cathédrale de Gdańsk-Oliwa, palais des Abbés d''Oliwa, phare de Sopot, forteresse de Wisłoujście…. 8 arrêts sur environ 25 km — réorganisez-les dans l''app et lancez la navigation."}, "uk": {"name": "Найкраще навколо: Katedrála Nejsvětější Trojice, Panny Marie a svatého Bernarda v Gdaňsku", "description": "Поїздка цікавими місцями у Польщі: Базиліка Святої Трійці, Пресвятої Богородиці та святого Бернара, Abbot''s Palace (Oliwa), Maják v Sopotech, Фортеця Віслоуйсьце…. Загалом 8 зупинок на приблизно 25 км — порядок можна змінити в застосунку й одразу навігувати."}}'::jsonb);

